import { sql, type Kysely } from 'kysely';

/**
 * Phase 1 foundation schema (plan §4.1, §10.2).
 * Plain SQL so it can be reviewed line by line. Every table: UUID v7 id (generated by the API),
 * created_at / updated_at. Records with history are deactivated, never hard-deleted.
 */
export async function up(db: Kysely<unknown>): Promise<void> {
  await sql`
    CREATE TYPE user_status AS ENUM ('invited','pending','active','suspended','deactivated');
    CREATE TYPE verification_status AS ENUM ('pending','verified','rejected','more_info_needed');
    CREATE TYPE org_type AS ENUM ('vta','employer','partner');
    CREATE TYPE app_role AS ENUM (
      'super_admin','ops_admin','centre_admin','employer_admin','employer_recruiter',
      'learner','partner_admin','partner_viewer','trainer'
    );

    CREATE TABLE users (
      id uuid PRIMARY KEY,
      name text NOT NULL CHECK (length(name) BETWEEN 2 AND 120),
      email text,
      phone text,
      password_hash text,
      email_verified_at timestamptz,
      phone_verified_at timestamptz,
      date_of_birth date,
      status user_status NOT NULL DEFAULT 'invited',
      failed_login_count integer NOT NULL DEFAULT 0,
      locked_until timestamptz,
      last_login_at timestamptz,
      created_at timestamptz NOT NULL DEFAULT now(),
      updated_at timestamptz NOT NULL DEFAULT now(),
      CONSTRAINT users_contact_required CHECK (email IS NOT NULL OR phone IS NOT NULL),
      CONSTRAINT users_email_lower CHECK (email IS NULL OR email = lower(email)),
      CONSTRAINT users_phone_e164 CHECK (phone IS NULL OR phone ~ '^\\+[1-9][0-9]{7,14}$')
    );
    CREATE UNIQUE INDEX users_email_key ON users (email) WHERE email IS NOT NULL;
    CREATE UNIQUE INDEX users_phone_key ON users (phone) WHERE phone IS NOT NULL;
    CREATE INDEX users_status_idx ON users (status);

    CREATE TABLE sessions (
      id uuid PRIMARY KEY,
      user_id uuid NOT NULL REFERENCES users(id),
      token_hash text NOT NULL UNIQUE,
      csrf_token text NOT NULL,
      idle_timeout_seconds integer NOT NULL,
      last_seen_at timestamptz NOT NULL DEFAULT now(),
      expires_at timestamptz NOT NULL,
      revoked_at timestamptz,
      ip text,
      user_agent text,
      created_at timestamptz NOT NULL DEFAULT now()
    );
    CREATE INDEX sessions_user_idx ON sessions (user_id) WHERE revoked_at IS NULL;

    CREATE TABLE otp_challenges (
      id uuid PRIMARY KEY,
      phone text NOT NULL,
      code_hash text NOT NULL,
      purpose text NOT NULL CHECK (purpose IN ('login')),
      expires_at timestamptz NOT NULL,
      attempts integer NOT NULL DEFAULT 0,
      consumed_at timestamptz,
      ip text,
      created_at timestamptz NOT NULL DEFAULT now()
    );
    CREATE INDEX otp_phone_idx ON otp_challenges (phone, created_at DESC);

    CREATE TABLE invitations (
      id uuid PRIMARY KEY,
      user_id uuid NOT NULL REFERENCES users(id),
      token_hash text NOT NULL UNIQUE,
      invited_by uuid NOT NULL REFERENCES users(id),
      expires_at timestamptz NOT NULL,
      accepted_at timestamptz,
      created_at timestamptz NOT NULL DEFAULT now()
    );

    CREATE TABLE organisations (
      id uuid PRIMARY KEY,
      type org_type NOT NULL,
      partner_subtype text,
      legal_name text NOT NULL,
      registration_ids jsonb NOT NULL DEFAULT '{}'::jsonb,
      address text,
      contact_name text,
      contact_email text,
      contact_phone text,
      verification_status verification_status NOT NULL DEFAULT 'pending',
      verification_reason text,
      verified_by uuid REFERENCES users(id),
      verified_at timestamptz,
      status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
      created_at timestamptz NOT NULL DEFAULT now(),
      updated_at timestamptz NOT NULL DEFAULT now(),
      CONSTRAINT org_partner_subtype CHECK (type <> 'partner' OR partner_subtype IS NOT NULL)
    );
    CREATE INDEX organisations_type_idx ON organisations (type, verification_status);

    CREATE TABLE centres (
      id uuid PRIMARY KEY,
      organisation_id uuid REFERENCES organisations(id),
      name text NOT NULL,
      address text,
      city text,
      contact_phone text,
      status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
      created_at timestamptz NOT NULL DEFAULT now(),
      updated_at timestamptz NOT NULL DEFAULT now()
    );
    CREATE INDEX centres_org_idx ON centres (organisation_id);

    CREATE TABLE role_assignments (
      id uuid PRIMARY KEY,
      user_id uuid NOT NULL REFERENCES users(id),
      role app_role NOT NULL,
      organisation_id uuid REFERENCES organisations(id),
      centre_id uuid REFERENCES centres(id),
      programme_id uuid, -- FK added when programmes arrive (Phase 7)
      granted_by uuid REFERENCES users(id),
      granted_at timestamptz NOT NULL DEFAULT now(),
      revoked_by uuid REFERENCES users(id),
      revoked_at timestamptz
    );
    CREATE INDEX role_assignments_user_idx ON role_assignments (user_id) WHERE revoked_at IS NULL;
    -- One active grant per user + role + scope
    CREATE UNIQUE INDEX role_assignments_active_key ON role_assignments (
      user_id, role,
      coalesce(organisation_id, '00000000-0000-0000-0000-000000000000'),
      coalesce(centre_id, '00000000-0000-0000-0000-000000000000')
    ) WHERE revoked_at IS NULL;

    CREATE TABLE audit_events (
      id uuid PRIMARY KEY,
      actor_id uuid REFERENCES users(id),
      action text NOT NULL,
      entity_type text NOT NULL,
      entity_id uuid,
      request_id text,
      before jsonb,
      after jsonb,
      ip text,
      created_at timestamptz NOT NULL DEFAULT now()
    );
    CREATE INDEX audit_entity_idx ON audit_events (entity_type, entity_id);
    CREATE INDEX audit_actor_idx ON audit_events (actor_id, created_at DESC);
    CREATE INDEX audit_created_idx ON audit_events (created_at DESC);

    -- Audit log is append-only (SEC-05, F-07). This trigger blocks UPDATE and DELETE
    -- for every database role, including the table owner the app connects as.
    CREATE FUNCTION audit_events_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      RAISE EXCEPTION 'audit_events is append-only';
    END $$;
    CREATE TRIGGER audit_events_no_update BEFORE UPDATE OR DELETE ON audit_events
      FOR EACH ROW EXECUTE FUNCTION audit_events_immutable();
    CREATE TRIGGER audit_events_no_truncate BEFORE TRUNCATE ON audit_events
      FOR EACH STATEMENT EXECUTE FUNCTION audit_events_immutable();
  `.execute(db);
}

export async function down(db: Kysely<unknown>): Promise<void> {
  await sql`
    DROP TABLE IF EXISTS audit_events, role_assignments, centres, organisations,
      invitations, otp_challenges, sessions, users CASCADE;
    DROP FUNCTION IF EXISTS audit_events_immutable();
    DROP TYPE IF EXISTS app_role, org_type, verification_status, user_status;
  `.execute(db);
}
